/**
 * Compiled from `registry/ui/alert.tsx` by `scripts/rn2web`.
 * Do not edit — edit the source and re-run `npm run compile`.
 *
 * The prose below is the source's own, carried across untouched, which is the property that makes
 * a compiled registry worth having: this is the same component, not a second one to keep in step
 * by hand. Where a comment names a React Native component it is describing the source; the
 * element map in `scripts/rn2web/tables.mjs` says what that became here.
 */

/**
 * A callout: a tinted, bordered box with an icon, a title, a line under it and an optional action.
 * The parts are props (`iconSlot`, `title`, `description`, `actionSlot`), and shadcn's compound
 * form with `AlertTitle` and `AlertDescription` works too, so a DOM call site ports unchanged.
 *
 * The variant colours only the tint, the border and the icon. The text is never the hue, because
 * coloured text on a 10% tint of the same colour is under 4.5:1. The title is the
 * foreground and the line under it `/60` in every variant, one hierarchy whatever the tint: `/60`
 * is 4.8:1 or more on each tint over the page and over a card, in every palette, and
 * `palette-contrast.test.mjs` holds it. Only `destructive` is `role="alert"`, which interrupts a
 * screen reader; the other variants are `status`.
 *
 * Written with the props, every variant keeps the icon's column, so a stack of alerts starts its
 * words at one edge. `info` has no glyph of its own (a highlight is not a kind of message, and an ⓘ
 * would argue with one that says "new" or "tip"), so with nothing passed its column is held empty.
 * The compound form keeps shadcn's look: with no icon child, the words start at the edge.
 */
import { Children, isValidElement, type ReactNode } from "react";
import { IconClassContext } from "@/components/ui/icons-base";
import { cn, type SlotNode } from "@/lib/utils";
import { CircleAlert, Info, TriangleAlert } from "@/components/ui/icons";

/** The kinds of callout, which pick its tint, icon and role. */
export type AlertVariant = "default" | "info" | "warning" | "destructive";

export type AlertProps = {
  /**
   * What kind of notice it is, which sets the tint, the icon and the role. `destructive` is an
   * error the reader has to hear now and is announced as an `alert`; the others are a `status`.
   */
  variant?: AlertVariant | undefined;
  /**
   * Before the title. A bare `<RefreshCw />`; the alert sizes it and gives it the variant's ink.
   * Left out, the variant's own glyph is drawn — `Info`, `TriangleAlert` or `CircleAlert` — except
   * on `info`, which has no glyph of its own: its column is held empty, so its words line up with
   * the alerts around it. `null` draws no icon and no column, and the text moves to the edge.
   */
  iconSlot?: SlotNode | undefined;
  /** What happened, in a few words: "API key generated", "Last error". */
  title?: ReactNode | undefined;
  /** The line under the title: what it means, or what to do about it. A link may sit inside it. */
  description?: ReactNode | undefined;
  /** The far end: one button that deals with it — "Change the embedder", "Retry". */
  actionSlot?: SlotNode | undefined;
  /** On the alert's box, the tinted surface around the icon, the words and the action. */
  className?: string | undefined;
  /**
   * shadcn's compound form: `AlertTitle`, `AlertDescription`, and an icon. See the header for how
   * they are placed. The props are the form to write here; this is the form to port.
   */
  children?: ReactNode;
};

export type AlertTitleProps = { className?: string | undefined; children?: ReactNode };
export type AlertDescriptionProps = { className?: string | undefined; children?: ReactNode };

/** The box: the tint and the border that names its colour, per variant. */
const ALERT_SURFACE = {
  default: "border border-foreground/10 bg-secondary",
  info: "border border-info/40 bg-info/10",
  warning: "border border-warning/40 bg-warning/10",
  destructive: "border border-negative/40 bg-negative/10",
} satisfies Record<AlertVariant, string>;

/** The icon's colour, and the only place the variant's hue reaches something drawn. */
const ALERT_ICON_INK = {
  default: "text-foreground",
  info: "text-info",
  warning: "text-warning",
  destructive: "text-negative",
} satisfies Record<AlertVariant, string>;

/**
 * The variant's own glyph, for when the caller passes no `iconSlot`. `info` has none: it is the
 * blue and nothing else, so the same alert can say "new" or "tip" without an ⓘ arguing with it.
 */
function defaultIcon(variant: AlertVariant): ReactNode {
  if (variant === "info") {
    return null;
  }
  if (variant === "destructive") {
    return <CircleAlert />;
  }
  if (variant === "warning") {
    return <TriangleAlert />;
  }
  return <Info />;
}

/** shadcn's `AlertTitle`: the title, for the compound form. */
export function AlertTitle({ className, children }: AlertTitleProps) {
  return (
    <span
      data-slot="alert-title"
      className={cn("cube-rn-text", "font-semibold text-foreground text-sm", className)}
    >
      {children}
    </span>
  );
}

/**
 * Whether a description is a run of text: a string, or text with a link or an emphasis inside it.
 * Anything with no loose text is a block, such as a list or a paragraph or two, and is not one.
 */
function isInlineText(children: ReactNode): boolean {
  return Children.toArray(children).some(
    (child) => typeof child === "string" || typeof child === "number",
  );
}

/**
 * shadcn's `AlertDescription`: the line under the title, in secondary ink on every variant.
 *
 * Text is a text element, as it was. Elements with no loose text around them (a `<ul>` of reasons,
 * a couple of `<p>`s) go in a box instead, because a list inside a `<span>` is invalid HTML (#358).
 * On the web the box hands the ink down; on device each `Text` inside takes its own.
 */
export function AlertDescription({ className, children }: AlertDescriptionProps) {
  const classes = cn("text-foreground/60 text-sm", className);
  if (isInlineText(children)) {
    return (
      <span data-slot="alert-description" className={cn("cube-rn-text", classes)}>
        {children}
      </span>
    );
  }
  return (
    <div data-slot="alert-description" className={cn("cube-rn-view", "gap-1", classes)}>
      {children}
    </div>
  );
}

/** Whether a child is one of the two text parts, which go into the column rather than the icon box. */
function isTextPart(child: ReactNode): boolean {
  return isValidElement(child) && (child.type === AlertTitle || child.type === AlertDescription);
}

/** A callout: a tinted box with an icon, a title, a description and an optional action. */
export function Alert({
  variant = "default",
  iconSlot,
  title,
  description,
  actionSlot,
  className,
  children,
}: AlertProps) {
  // A bare string is the description, wrapped so native never puts text straight into a `View`.
  const parts = Children.toArray(children).map((child) =>
    typeof child === "string" || typeof child === "number" ? (
      <AlertDescription key={String(child)}>{child}</AlertDescription>
    ) : (
      child
    ),
  );
  const textParts = parts.filter(isTextPart);
  const iconParts = parts.filter((child) => isTextPart(child) === false);
  const ownIcon = parts.length > 0 ? null : defaultIcon(variant);
  const glyph = iconSlot !== undefined ? iconSlot : ownIcon;
  const ink = ALERT_ICON_INK[variant];
  // Held empty only when nothing chose otherwise: `null`, or children of the compound form, do.
  const drawn = Boolean(glyph) || iconParts.length > 0;
  const column = drawn || (iconSlot === undefined && parts.length === 0);

  return (
    <div
      data-slot="alert"
      role={variant === "destructive" ? "alert" : "status"}
      className={cn(
        "cube-rn-view",
        "w-full min-w-0 flex-row items-start gap-3 rounded-lg px-4 py-3",
        ALERT_SURFACE[variant],
        className,
      )}
    >
      {column ? (
        <div
          data-slot="alert-icon"
          aria-hidden
          className={cn(
            "cube-rn-view",
            "mt-0.5 shrink-0 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
            drawn ? undefined : "w-4",
            ink,
          )}
        >
          <IconClassContext.Provider value={cn("size-4 shrink-0", ink)}>
            {glyph}
            {iconParts}
          </IconClassContext.Provider>
        </div>
      ) : null}
      <div className="cube-rn-view min-w-0 flex-1 gap-1">
        {title ? <AlertTitle>{title}</AlertTitle> : null}
        {description ? <AlertDescription>{description}</AlertDescription> : null}
        {textParts}
      </div>
      {actionSlot ? (
        <div data-slot="alert-action" className="cube-rn-view shrink-0 self-center">
          {actionSlot}
        </div>
      ) : null}
    </div>
  );
}
